class TestRegression:
    """Verify no regressions in previously fixed issues."""

    def test_regression_negative_coefficients(self, solver: MathSolver):
        """Should handle negative coefficients correctly."""
        result = solver.solve("-x + 2 = 0", SolveMode.EXACT)
        assert abs(result.value[0] - 2) < 1e-10

    def test_regression_decimal_coefficients(self, solver: MathSolver):
        """Should handle decimal coefficients correctly."""
        result = solver.solve("0.5*x + 1.5 = 0", SolveMode.EXACT)
        assert abs(result.value[0] - (-3)) < 1e-10

    def test_regression_fractional_exponents(self, solver: MathSolver):
        """Should handle fractional exponents correctly."""
        result = solver.solve("x**(1/2) - 2 = 0", SolveMode.EXACT)
        assert abs(result.value[0] - 4) < 1e-10

    def test_regression_nested_functions(self, solver: MathSolver):
        """Should handle nested functions correctly."""
        result = solver.solve("sin(cos(x)) = 0", SolveMode.NUMERICAL)
        assert len(result.value) > 0


# =============================================================================
# Test Concurrency (Simulated)
# =============================================================================

class TestConcurrency:
    """Verify the solver handles concurrent access safely."""

    def test_concurrent_solves(self, solver: MathSolver):
        """Should handle multiple concurrent solve requests."""
        import threading
        results = []
        errors = []

        def solve_equation(eq: str):
            try:
                result = solver.solve(eq, SolveMode.EXACT)
                results.append(result)
            except Exception as e:
                errors.append(e)

        threads = []
        equations = [
            "x + 1 = 0",
            "x - 2 = 0",
            "x**2 - 4 = 0",
            "sin(x) = 0",
            "exp(x) - 1 = 0",
        ]
        for eq in equations:
            t = threading.Thread(target=solve_equation, args=(eq,))
            threads.append(t)
            t.start()

        for t in threads:
            t.join()

        assert len(errors) == 0
        assert len(results) == len(equations)
        assert all(isinstance(r, SolverResult) for r in results)


